package com.mahesh.empleave;
import com.mahesh.empleave.audit.*;import com.mahesh.empleave.holiday.*;import com.mahesh.empleave.leave.*;import com.mahesh.empleave.leavebalance.*;import com.mahesh.empleave.leavetype.*;import com.mahesh.empleave.notification.*;import com.mahesh.empleave.user.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.*;import org.mockito.*;import org.mockito.junit.jupiter.*;import org.springframework.test.util.ReflectionTestUtils;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class LeaveServiceTest{
 @Mock LeaveRepository leaves;@Mock UserRepository users;@Mock LeaveTypeRepository types;@Mock LeaveBalanceRepository balances;@Mock BalanceTransactionRepository transactions;@Mock HolidayRepository holidays;@Mock AuditService audit;@Mock NotificationService notifications;@InjectMocks LeaveService service;
 @Test void workingDaysExcludesWeekendsAndHolidays(){when(holidays.findByHolidayDateBetween(LocalDate.of(2026,11,2),LocalDate.of(2026,11,8))).thenReturn(List.of(new Holiday(LocalDate.of(2026,11,4),"Festival")));assertEquals(4,service.workingDays(LocalDate.of(2026,11,2),LocalDate.of(2026,11,8)));}
 @Test void balanceCannotBeDebitedBelowZero(){var b=new LeaveBalance(new AppUser("x@y.com","x",Role.EMPLOYEE,"X"),new LeaveType("Annual"),BigDecimal.ONE);assertThrows(IllegalStateException.class,()->b.debit(2));}
 @Test void duplicateApprovalDoesNotCreateSecondTransaction(){var employee=user(1L,"employee@x",Role.EMPLOYEE);var manager=user(2L,"manager@x",Role.MANAGER);ReflectionTestUtils.setField(employee,"manager",manager);var leave=new LeaveApplication(employee,"Annual",LocalDate.now().plusDays(3),LocalDate.now().plusDays(3),1,"reason");ReflectionTestUtils.setField(leave,"id",99L);var type=new LeaveType("Annual");var balance=new LeaveBalance(employee,type,BigDecimal.TEN);when(users.findByEmail(manager.getEmail())).thenReturn(Optional.of(manager));when(leaves.findById(99L)).thenReturn(Optional.of(leave));when(types.findByNameAndActiveTrue("Annual")).thenReturn(Optional.of(type));when(balances.findForUpdate(employee,type)).thenReturn(Optional.of(balance));when(transactions.existsByApplication(leave)).thenReturn(false,true);service.approve(manager.getEmail(),99L);assertEquals(BigDecimal.valueOf(9),balance.getRemainingDays());assertThrows(IllegalStateException.class,()->service.approve(manager.getEmail(),99L));verify(transactions,times(1)).save(any());}
 @Test void approvedFutureCancellationRestoresBalance(){var employee=user(1L,"employee@x",Role.EMPLOYEE);var manager=user(2L,"manager@x",Role.MANAGER);ReflectionTestUtils.setField(employee,"manager",manager);var leave=new LeaveApplication(employee,"Annual",LocalDate.now().plusDays(3),LocalDate.now().plusDays(3),1,"reason");ReflectionTestUtils.setField(leave,"id",91L);leave.approve();var type=new LeaveType("Annual");var balance=new LeaveBalance(employee,type,BigDecimal.valueOf(9));when(users.findByEmail(employee.getEmail())).thenReturn(Optional.of(employee));when(leaves.findById(91L)).thenReturn(Optional.of(leave));when(types.findByNameAndActiveTrue("Annual")).thenReturn(Optional.of(type));when(balances.findForUpdate(employee,type)).thenReturn(Optional.of(balance));service.cancel(employee.getEmail(),91L);assertEquals(LeaveStatus.CANCELLED,leave.getStatus());assertEquals(BigDecimal.TEN,balance.getRemainingDays());verify(transactions).save(any());}
 @Test void insufficientBalanceDoesNotWriteAccountingTransaction(){var employee=user(1L,"employee@x",Role.EMPLOYEE);var manager=user(2L,"manager@x",Role.MANAGER);ReflectionTestUtils.setField(employee,"manager",manager);var leave=new LeaveApplication(employee,"Annual",LocalDate.now().plusDays(3),LocalDate.now().plusDays(5),3,"reason");ReflectionTestUtils.setField(leave,"id",70L);var type=new LeaveType("Annual");var balance=new LeaveBalance(employee,type,BigDecimal.ONE);when(users.findByEmail(manager.getEmail())).thenReturn(Optional.of(manager));when(leaves.findById(70L)).thenReturn(Optional.of(leave));when(types.findByNameAndActiveTrue("Annual")).thenReturn(Optional.of(type));when(balances.findForUpdate(employee,type)).thenReturn(Optional.of(balance));when(transactions.existsByApplication(leave)).thenReturn(false);assertThrows(IllegalStateException.class,()->service.approve(manager.getEmail(),70L));assertEquals(LeaveStatus.PENDING,leave.getStatus());verify(transactions,never()).save(any());}
 private AppUser user(Long id,String email,Role role){var u=new AppUser(email,"x",role,email);ReflectionTestUtils.setField(u,"id",id);return u;}}
